<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Key\Infrastructure\Driven;

use PDO;
use Override;
use Civi\Lughauth\Features\Oidc\Key\Domain\Gateway\TokenRevocationGateway;

class TokenRevocationSqlAdapter implements TokenRevocationGateway
{
    public function __construct(private readonly PDO $pdo)
    {
    }

    #[Override]
    public function revokeJti(string $jti, string $tenantId, string $tokenType, \DateTimeImmutable $expiresAt): void
    {
        $stmt = $this->pdo->prepare(
            'INSERT IGNORE INTO _oauth_revoked_jti (jti, tenant_id, token_type, expires_at)
             VALUES (:jti, :tenant_id, :token_type, :expires_at)'
        );
        $stmt->bindValue('jti', $jti, PDO::PARAM_STR);
        $stmt->bindValue('tenant_id', $tenantId, PDO::PARAM_STR);
        $stmt->bindValue('token_type', $tokenType, PDO::PARAM_STR);
        $stmt->bindValue('expires_at', $expiresAt->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->execute();
    }

    #[Override]
    public function isRevoked(string $jti, string $tenantId): bool
    {
        $stmt = $this->pdo->prepare(
            'SELECT 1 FROM _oauth_revoked_jti WHERE jti = :jti AND tenant_id = :tenant_id LIMIT 1'
        );
        $stmt->bindValue('jti', $jti, PDO::PARAM_STR);
        $stmt->bindValue('tenant_id', $tenantId, PDO::PARAM_STR);
        $stmt->execute();
        return (bool) $stmt->fetchColumn();
    }

    #[Override]
    public function cleanup(): void
    {
        $this->pdo->exec('DELETE FROM _oauth_revoked_jti WHERE expires_at < NOW()');
    }
}
